var iconCache = map[string]*ui.SVG{}

const svgHead = `<svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round">`

// icon shows a named icon at iconSize in the given text colour. The view runs on one goroutine, so the cache needs no lock.
func icon(c *ui.Context, name string, col ui.Color) ui.Element {
	return iconSized(c, name, col, iconSize)
}

func iconSized(c *ui.Context, name string, col ui.Color, size float32) ui.Element {
	s, ok := iconCache[name]
	if !ok {
		body, found := iconPaths[name]
		if !found {
			panic("icon: unknown " + name)
		}
		s = ui.MustParseSVG([]byte(svgHead + body + "</svg>"))
		iconCache[name] = s
	}
	return ui.Icon(c, s).FontSize(size).TextColor(col)
}
